states.2405deefa4bb:
[
 {
  "tur": "başvuru notu",
  "zaman": "2026-09-30 10:05",
  "metin": "Müşteri Yusuf Kalkavan, 'parası içeride kaldığı' yatırım kanalının son bir aylık Telegram dökümünü şubeye iletti. Döküm aşağıdadır; görseller metin olarak aktarılmamıştır. Kanal: 'Arbitraj Kulübü TR' (yönetici: Kaptan Arbi, moderatör: Elçin)."
 },
 {
  "zaman": "2026-08-28 09:00",
  "gonderen": "Kaptan Arbi",
  "metin": "Günaydın kulüp! Bugün arbitraj botumuz BTC/USDT paritesinde üç borsa arasında güzel bir fark yakaladı. Bot kullanıcılarına günlük %2,5 getiri dağıtıldı. Henüz katılmayanlar sabitlenmiş mesajdaki bağlantıdan Nexvault'a kayıt olabilir."
 },
 {
  "zaman": "2026-08-28 09:14",
  "gonderen": "Hilal",
  "metin": "Kaptan kayıt oldum, ilk yatırım en az ne kadar olmalı?"
 },
 {
  "zaman": "2026-08-28 09:20",
  "gonderen": "Elçin (moderatör)",
  "metin": "Minimum 250 USDT. Ama 1.000 USDT ve üstü 'Altın Paket' daha hızlı kazandırıyor, bot önceliği onlarda."
 },
 {
  "zaman": "2026-08-28 12:41",
  "gonderen": "Kaptan Arbi",
  "metin": "Piyasa notu: Fed toplantısı öncesi oynaklık düşük. Arbitraj botları için bu ideal, çünkü borsalar arasındaki fiyat farkları daha uzun süre açık kalıyor ve bot daha rahat işlem yapıyor."
 },
 {
  "zaman": "2026-08-29 18:00",
  "gonderen": "Elçin (moderatör)",
  "metin": "Hafta sonu çekilişi: 5 kişiye 100'er USDT! Katılmak için kanalı paylaşın ve en az üç arkadaşınızı davet edin. Sonuçlar pazar akşamı açıklanacak."
 },
 {
  "zaman": "2026-08-30 11:32",
  "gonderen": "Rıza",
  "metin": "Dün 300 USDT çektim, iki saatte cüzdanıma geldi. Teşekkürler kaptan, ilk başta inanmamıştım açıkçası."
 },
 {
  "zaman": "2026-08-31 20:10",
  "gonderen": "Kaptan Arbi",
  "metin": "Avrupa lisanslı bir platformla çalışıyoruz, gönül rahatlığıyla yatırabilirsiniz. Biz kimsenin parasına dokunmuyoruz, para sizin hesabınızda duruyor, bot sadece işlem yapıyor."
 },
 {
  "zaman": "2026-09-01 09:30",
  "gonderen": "Kaptan Arbi",
  "metin": "Eylülün ilk günü: botun ağustos performansı %71. Ekran görüntüsünü aşağıya bırakıyorum. Bu performansı bankada, altında, dövizde bulamazsınız."
 },
 {
  "zaman": "2026-09-02 14:22",
  "gonderen": "Ozan",
  "metin": "Kaptan bu kazançlardan vergi çıkar mı, beyan etmem gerekir mi?"
 },
 {
  "zaman": "2026-09-02 14:30",
  "gonderen": "Elçin (moderatör)",
  "metin": "Vergi konusunda kendi mali müşavirinize danışın, biz vergi danışmanlığı vermiyoruz."
 },
 {
  "zaman": "2026-09-03 21:15",
  "gonderen": "Kaptan Arbi",
  "metin": "Litvanya'daki blockchain fuarından yeni döndüm. Yeni iş ortaklarıyla görüştük, kulüp için güzel haberler yolda. Fuardan fotoğrafları yarın paylaşacağım."
 },
 {
  "zaman": "2026-09-04 10:02",
  "gonderen": "Kaptan Arbi",
  "metin": "Ethereum tarafında ağ ücretleri son haftaların en düşük seviyesinde. Transferlerinizi bu dönemde yapmanız maliyet açısından avantajlı olur."
 },
 {
  "zaman": "2026-09-04 10:20",
  "gonderen": "Tamer",
  "metin": "Kaptan geçen hafta konuştuğumuz Solana ağındaki tıkanıklık çözüldü mü? Arkadaşım transferinin saatlerce beklediğini söyledi, ben de oradan göndermeyi düşünüyordum."
 },
 {
  "zaman": "2026-09-04 10:34",
  "gonderen": "Kaptan Arbi",
  "metin": "Çözüldü, ama bizim bot zaten Solana ağında işlem yapmıyor. Yine de büyük tutarları göndermeden önce küçük bir deneme transferi yapmanızı öneririm, bu her ağ için iyi bir alışkanlık."
 },
 {
  "zaman": "2026-09-05 08:15",
  "gonderen": "Bülent",
  "metin": "Günaydın arkadaşlar. Dün akşamki yayını kaçırdım, kaydı olan var mı? Bir de altın paketin süresi kaç ay, onu anlamadım."
 },
 {
  "zaman": "2026-09-05 08:40",
  "gonderen": "Elçin (moderatör)",
  "metin": "Yayın kaydı sabitlenmiş mesajda. Paketlerin süresi yok, bakiyeniz durdukça bot çalışmaya devam eder. Paket yükseltmek için destek hattına yazmanız yeterli."
 },
 {
  "zaman": "2026-09-05 16:40",
  "gonderen": "Melis",
  "metin": "Arkadaşlar USDT'yi nereden alıyorsunuz, Türkiye'deki borsalardan mı?"
 },
 {
  "zaman": "2026-09-05 16:48",
  "gonderen": "Elçin (moderatör)",
  "metin": "Kullandığınız bir borsadan alıp Nexvault'taki cüzdan adresinize gönderebilirsiniz. Ağ seçimini mutlaka TRC20 yapın, yanlış ağ seçerseniz para kaybolur."
 },
 {
  "zaman": "2026-09-07 09:05",
  "gonderen": "Kaptan Arbi",
  "metin": "Altın Paket kullanıcılarına bu hafta günlük %3 getiri! Normal paket kullanıcıları da %2,5'te devam ediyor. Paket yükseltmek isteyenler destek hattına yazsın."
 },
 {
  "zaman": "2026-09-08 13:12",
  "gonderen": "Bülent",
  "metin": "Tebrikler kaptan, eşimi de ekledim. Bu ay emekli ikramiyesinin bir kısmını da koyacağız."
 },
 {
  "zaman": "2026-09-09 19:45",
  "gonderen": "Kaptan Arbi",
  "metin": "Bitcoin'de dört saatlik grafikte daralan üçgen var, kırılım yönü önemli. Ama bizim bot yön tahmini yapmadığı için bu hareketlerden etkilenmiyor, sadece fiyat farkından kazanıyor."
 },
 {
  "zaman": "2026-09-09 20:02",
  "gonderen": "Ozan",
  "metin": "Kaptan bir de altcoin sepeti yapsanız ya, bazı kanallar haftada yüzde elli kazandırıyormuş diye duydum. Bizim bot sadece büyük paritelerde mi çalışıyor?"
 },
 {
  "zaman": "2026-09-09 20:15",
  "gonderen": "Kaptan Arbi",
  "metin": "Haftada yüzde elli diyenlerden uzak durun, onlar kumar. Biz düşük riskli arbitraj yapıyoruz, sadece likiditesi yüksek paritelerde. Altcoin sepeti şu an gündemimizde yok."
 },
 {
  "zaman": "2026-09-09 21:30",
  "gonderen": "Hilal",
  "metin": "Herkese iyi geceler, bu hafta işler yoğundu, kanalı ancak okuyabildim. Bot sayesinde bu ay kira derdim olmadı, kaptana teşekkürler."
 },
 {
  "zaman": "2026-09-10 08:30",
  "gonderen": "Elçin (moderatör)",
  "metin": "Kanal kuralları hatırlatma: reklam, başka kanal linki ve küfür yasak. Özelden size yazan 'yönetici'lere itibar etmeyin, bizim ekibimiz size ilk yazmaz."
 },
 {
  "zaman": "2026-09-12 15:05",
  "gonderen": "Hilal",
  "metin": "Çekim talebim iki gündür beklemede görünüyor, normal mi?"
 },
 {
  "zaman": "2026-09-12 15:20",
  "gonderen": "Elçin (moderatör)",
  "metin": "Yoğunluk nedeniyle çekimler 72 saate kadar sürebilir, lütfen sabırlı olun."
 },
 {
  "zaman": "2026-09-13 11:05",
  "gonderen": "Kaptan Arbi",
  "metin": "Cumartesi notu: bu hafta küresel piyasalarda enflasyon verisi beklentinin biraz altında geldi, risk iştahı arttı. Kripto tarafında işlem hacimleri yükseldi, bu da botun daha fazla fırsat yakalaması demek. Hafta sonu herkese iyi dinlenmeler, pazartesi yeni haftanın hedeflerini paylaşacağım."
 },
 {
  "zaman": "2026-09-13 11:40",
  "gonderen": "Melis",
  "metin": "Kaptan, telefondan panele girerken sürekli oturum kapanıyor, bilgisayardan sorun yok. Başka yaşayan var mı? Uygulama mağazasında Nexvault'un uygulamasını bulamadım, tarayıcıdan giriyorum."
 },
 {
  "zaman": "2026-09-13 12:02",
  "gonderen": "Elçin (moderatör)",
  "metin": "Uygulama şu an sadece tarayıcı sürümünde. Oturum sorunu için tarayıcı önbelleğini temizlemeniz yeterli, olmazsa destek hattına ekran görüntüsüyle yazın."
 },
 {
  "zaman": "2026-09-14 22:51",
  "gonderen": "Kaptan Arbi",
  "metin": "Kısa bir teknik bilgi: Nexvault'ta kartla ve kripto ile yatırma yoğunluk nedeniyle geçici olarak kapalı. TL ile yatırmak isteyenler bu hafta P2P temsilcimiz Sercan Bey'in kendi banka hesabına havale yapsın (IBAN özelden iletilir), açıklamaya sadece adınızı yazın. Bakiyeniz 24 saat içinde USDT olarak tanımlanır."
 },
 {
  "zaman": "2026-09-15 10:10",
  "gonderen": "Tamer",
  "metin": "Kaptan botun stratejisi tam olarak ne? Hangi borsalar arasında işlem yapıyor?"
 },
 {
  "zaman": "2026-09-15 10:25",
  "gonderen": "Kaptan Arbi",
  "metin": "Ticari sır, detay veremem. Kısaca üç büyük borsa arasındaki fiyat farkından kâr ediyoruz, risk sıfıra yakın."
 },
 {
  "zaman": "2026-09-16 17:02",
  "gonderen": "Kaptan Arbi",
  "metin": "Bugün piyasada sert düşüş var ama bot nötr pozisyonda. Kulüp üyelerinin bakiyeleri bu düşüşten etkilenmez, panik yok."
 },
 {
  "zaman": "2026-09-17 11:48",
  "gonderen": "Rıza",
  "metin": "Benim 1.200 USDT'lik çekimim beş gündür gelmedi, destek hattından da cevap yok."
 },
 {
  "zaman": "2026-09-17 12:05",
  "gonderen": "Elçin (moderatör)",
  "metin": "Rıza Bey, hesabınızda 'doğrulama' adımı bekliyor, özelden yazdım."
 },
 {
  "zaman": "2026-09-19 20:30",
  "gonderen": "Kaptan Arbi",
  "metin": "Çekim yapamıyoruz diyenler: platform güvenlik güncellemesi yapıyor. 'Hesap doğrulama' tamamlanınca her şey normale dönecek."
 },
 {
  "zaman": "2026-09-20 09:14",
  "gonderen": "Yusuf",
  "metin": "Ben de geçen hafta TL yatırdım, bakiye göründü ama çekim butonu çalışmıyor."
 },
 {
  "zaman": "2026-09-21 18:00",
  "gonderen": "Elçin (moderatör)",
  "metin": "Pazar akşamı canlı yayın: 'Arbitraj nedir, nasıl çalışır?' Sorularınızı şimdiden bu mesajın altına yazabilirsiniz."
 },
 {
  "zaman": "2026-09-21 18:20",
  "gonderen": "Tamer",
  "metin": "Yayında şu soruyu cevaplarsanız sevinirim: bot hangi saatlerde işlem yapıyor ve hafta sonu da çalışıyor mu? Bir de bakiyeyi panelde TL olarak görebilir miyiz, her seferinde kuru hesaplamak zor oluyor."
 },
 {
  "zaman": "2026-09-21 18:35",
  "gonderen": "Bülent",
  "metin": "Benim sorum da şu: eşimin hesabıyla benim hesabımı birleştirebilir miyiz? Aynı evde iki ayrı hesap takip etmek karışık oluyor, yaşlı annem de katılmak istiyor."
 },
 {
  "zaman": "2026-09-21 19:10",
  "gonderen": "Kaptan Arbi",
  "metin": "Hepsini yayında konuşacağız. Kısaca: piyasa yirmi dört saat açık olduğu için bot da hafta sonu çalışıyor. Hesap birleştirme ve TL gösterimi yeni sürümde gelecek."
 },
 {
  "zaman": "2026-09-22 13:40",
  "gonderen": "Elçin (moderatör)",
  "metin": "Doğrulama hakkında çok soru geliyor: çekim yapabilmek için hesap bakiyenizin %8'i kadar 'doğrulama teminatı' yatırmanız gerekiyor. Doğrulama tamamlanınca bu tutar bakiyenize iade edilir."
 },
 {
  "zaman": "2026-09-23 08:55",
  "gonderen": "Melis",
  "metin": "Bu dolandırıcılık mı arkadaşlar? SPK'ya mı yazsak, savcılığa mı?"
 },
 {
  "zaman": "2026-09-23 09:02",
  "gonderen": "Elçin (moderatör)",
  "metin": "Lütfen panik yaratmayın. Grupta panik yaratan mesaj atanlar kanaldan çıkarılacaktır."
 },
 {
  "zaman": "2026-09-24 21:10",
  "gonderen": "Kaptan Arbi",
  "metin": "Botun eylül performansı da %60'ın üzerinde, endişeye gerek yok. Sabırlı olan kazanır."
 },
 {
  "zaman": "2026-09-25 07:40",
  "gonderen": "Hilal",
  "metin": "Kanalın yorumları neden kapatıldı? Kimse bir şey yazamıyor artık."
 },
 {
